import { Link } from 'react-router-dom';

const Footer = () => (
  <footer style={{
    background: 'var(--eco-surface)',
    borderTop: '1px solid var(--eco-border)',
    padding: '48px 24px 28px',
    marginTop: 'auto',
  }}>
    <div style={{ maxWidth: 1100, margin: '0 auto' }}>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))', gap: 32, marginBottom: 36 }}>

        {/* Brand */}
        <div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 12 }}>
            <div style={{ width: 32, height: 32, background: 'var(--eco-primary)', borderRadius: 8, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 16 }}>🌿</div>
            <span style={{ fontFamily: 'var(--font-display)', fontWeight: 700, fontSize: 18, color: 'var(--eco-primary)' }}>EcoTrack</span>
          </div>
          <p style={{ fontSize: 13, color: 'var(--eco-text-muted)', lineHeight: 1.7 }}>
            Smarter waste management for a cleaner, greener India.
          </p>
        </div>

        {/* Platform */}
        <div>
          <div style={{ fontWeight: 600, fontSize: 13, color: 'var(--eco-text)', marginBottom: 12, textTransform: 'uppercase', letterSpacing: '0.5px' }}>Platform</div>
          {[
            { to: '/',            label: 'Home' },
            { to: '/how-it-works', label: 'How It Works' },
            { to: '/rewards',     label: 'Rewards' },
            { to: '/about',       label: 'About Us' },
          ].map(l => (
            <Link key={l.to} to={l.to} style={{ display: 'block', fontSize: 13, color: 'var(--eco-text-secondary)', marginBottom: 8, textDecoration: 'none' }}
              onMouseEnter={e => e.target.style.color = 'var(--eco-primary)'}
              onMouseLeave={e => e.target.style.color = 'var(--eco-text-secondary)'}
            >{l.label}</Link>
          ))}
        </div>

        {/* Awareness */}
        <div>
          <div style={{ fontWeight: 600, fontSize: 13, color: 'var(--eco-text)', marginBottom: 12, textTransform: 'uppercase', letterSpacing: '0.5px' }}>Awareness</div>
          {[
            { to: '/blogs',     label: 'Blogs' },
            { to: '/campaigns', label: 'Campaigns' },
            { to: '/events',    label: 'Events' },
          ].map(l => (
            <Link key={l.to} to={l.to} style={{ display: 'block', fontSize: 13, color: 'var(--eco-text-secondary)', marginBottom: 8, textDecoration: 'none' }}
              onMouseEnter={e => e.target.style.color = 'var(--eco-primary)'}
              onMouseLeave={e => e.target.style.color = 'var(--eco-text-secondary)'}
            >{l.label}</Link>
          ))}
        </div>

        {/* Account */}
        <div>
          <div style={{ fontWeight: 600, fontSize: 13, color: 'var(--eco-text)', marginBottom: 12, textTransform: 'uppercase', letterSpacing: '0.5px' }}>Account</div>
          {[
            { to: '/login',    label: 'Sign In' },
            { to: '/register', label: 'Register' },
            { to: '/contact',  label: 'Contact' },
          ].map(l => (
            <Link key={l.to} to={l.to} style={{ display: 'block', fontSize: 13, color: 'var(--eco-text-secondary)', marginBottom: 8, textDecoration: 'none' }}
              onMouseEnter={e => e.target.style.color = 'var(--eco-primary)'}
              onMouseLeave={e => e.target.style.color = 'var(--eco-text-secondary)'}
            >{l.label}</Link>
          ))}
        </div>
      </div>

      <div style={{ borderTop: '1px solid var(--eco-border)', paddingTop: 20, display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 8 }}>
        <span style={{ fontSize: 12, color: 'var(--eco-text-muted)' }}>
          © 2026 EcoTrack. Clean India Green India 🌱
        </span>
        <span style={{ fontSize: 12, color: 'var(--eco-text-muted)' }}>
          Built with 💚 for sustainability
        </span>
      </div>
    </div>
  </footer>
);

export default Footer;
